keyframes.text:
@keyframes overload-shake { 
  0%, 100% { translate: 0px; }
  25% { translate: calc(var(--amp) * -1px) calc(var(--amp) * .6px); }
  50% { translate: calc(var(--amp) * .8px) calc(var(--amp) * -.6px); }
  75% { translate: calc(var(--amp) * -.5px) calc(var(--amp) * -.4px); }
}

reduced:
@media (prefers-reduced-motion: reduce) {
  .reveal, .logo-float, .rise, .stat-bar, .fps-range, .overload-shake, .overload-flow, .race-fill, .race-time { transition: none; animation: auto ease 0s 1 normal none running none; }
}
